#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""A negative test of the Step 1 parity checker — does it actually compare?

A checker that always reports success is useless, and there is no way to tell
that from watching it report success. This file deliberately skews one number
and demands that `dotnet test` and `flutter test` FAIL.

## Why only the GENERATED file is modified, never the source

The first version of this test edited a constant in
`backend/Api/Nutrition/NutritionTargets.cs` directly and restored it in a
`finally`. The session was cut off during the third case, and the `finally`
never ran — **the injected `BmiOverweightAsia = 25.0m` stayed in the real
source**, along with a `.thubak` file nobody noticed. The code still compiled,
still ran, it just classified BMI on the international thresholds instead of
the Asian ones.

So this test only modifies `data/buoc1_cases.json` — a file generated by
`tools/gen_buoc1_cases.py`. If it is cut off halfway, the worst consequence is
one file that regenerates with a single command, and `check_be_parity.py`
itself regenerates it as step 1 of every run.

The comparison is symmetric: skewing the fixture side proves the comparison is
alive just as well as skewing the source side would.

Run:
    python tools/test_be_parity.py
"""

from __future__ import annotations

import json
import os
import pathlib
import shutil
import subprocess
import sys

ROOT = pathlib.Path(__file__).resolve().parent.parent
CASES = ROOT / "data" / "buoc1_cases.json"
BACKEND = ROOT / "backend"
MOBILE = ROOT / "mobile"
DART_TEST = "test/buoc1_parity_test.dart"

#: (label, path inside the JSON, the function that skews it)
#:
#: Each case targets a different part of the calculation, so that one missing
#: comparison cannot hide behind another.
INJECTIONS = [
    ("age +1", ["age"], lambda v: v + 1),
    ("bmi +0.01", ["bmi"], lambda v: round(v + 0.01, 2)),
    ("BMI category changed", ["bmiCategory"],
     lambda v: "normal" if v != "normal" else "obese"),
    ("BMR +5 kcal", ["bmrKcal"], lambda v: v + 5),
    ("TDEE +1 kcal", ["tdeeKcal"], lambda v: v + 1),
    ("activity factor +0.005", ["activityFactor"],
     lambda v: round(v + 0.005, 3)),
    ("calorie limit +1", ["dailyCaloriesTarget"], lambda v: v + 1),
    ("protein +0.1 g", ["proteinG"], lambda v: round(v + 0.1, 1)),
    ("carbohydrate +0.1 g", ["carbsG"], lambda v: round(v + 0.1, 1)),
    ("fat +0.1 g", ["fatG"], lambda v: round(v + 0.1, 1)),
    ("lunch kcal +1", ["mealKcal", "lunch"], lambda v: v + 1),
]

#: The two file-level factor tables, which belong to no single case —
#: `Bang_he_so_khop_hai_chieu` on the C# side and the two matching Dart
#: assertions have to catch these.
TABLE_INJECTIONS = [
    ("factor table: an extra activity level",
     lambda payload: payload["activityFactor"].update({"extreme": 2.1})),
    ("factor table: moderate factor changed",
     lambda payload: payload["activityFactor"].update({"moderate": 1.6})),
    ("meal share table: no longer sums to 1.0",
     lambda payload: payload["mealShare"].update({"snack": 0.05})),
]

#: The case the errors are injected into. `spec-7.2.3` because it is the case
#: taken from the worked example in the specification.
TARGET_CASE = "spec-7.2.3"


def _use_utf8() -> None:
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8")  # type: ignore[union-attr]
        except Exception:
            pass


def regenerate() -> None:
    subprocess.run(
        [sys.executable, "tools/gen_buoc1_cases.py"], cwd=str(ROOT),
        capture_output=True, text=True,
        env=dict(os.environ, PYTHONIOENCODING="utf-8"), check=True,
    )


def run_both_suites() -> bool:
    """`True` if BOTH suites pass — meaning the injected error SLIPPED past."""
    env = dict(os.environ, PYTHONIOENCODING="utf-8")
    csharp = subprocess.run(
        [shutil.which("dotnet") or "dotnet", "test", "--nologo"],
        cwd=str(BACKEND), capture_output=True, text=True,
        encoding="utf-8", errors="replace", env=env)
    dart = subprocess.run(
        [shutil.which("flutter") or "flutter", "test", DART_TEST],
        cwd=str(MOBILE), capture_output=True, text=True,
        encoding="utf-8", errors="replace", env=env)
    return csharp.returncode == 0 and dart.returncode == 0


def apply_at_path(data: dict, path: list[str], mutate) -> bool:
    """Apply `mutate` to the value at `path`; `False` if the path is absent."""
    node = data
    for key in path[:-1]:
        if key not in node:
            return False
        node = node[key]
    last = path[-1]
    if last not in node:
        return False
    node[last] = mutate(node[last])
    return True


def main() -> int:
    _use_utf8()
    print("Negative test: does the Step 1 parity checker actually compare?")
    print("=" * 72)
    print("Only data/buoc1_cases.json is modified — a generated file. The")
    print("source is never touched, so being cut off halfway costs one")
    print("regenerated file.")
    print()

    regenerate()
    original = CASES.read_text(encoding="utf-8")
    slipped: list[str] = []

    try:
        for label, path, mutate in INJECTIONS:
            payload = json.loads(original)
            # `ten` is the case-name key in the generated JSON; see the note
            # on language in `gen_buoc1_cases.py`.
            case = next(c for c in payload["cases"] if c["ten"] == TARGET_CASE)
            if not apply_at_path(case["ra"], path, mutate):
                print(f"  [SKIPPED] {label} — no path "
                      f"{'.'.join(path)} in case {TARGET_CASE}")
                continue
            CASES.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            if run_both_suites():
                slipped.append(label)
                print(f"  [SLIPPED] {label}")
            else:
                print(f"  [caught]  {label}")

        for label, mutate in TABLE_INJECTIONS:
            payload = json.loads(original)
            mutate(payload)
            CASES.write_text(
                json.dumps(payload, ensure_ascii=False, indent=2) + "\n",
                encoding="utf-8",
            )
            if run_both_suites():
                slipped.append(label)
                print(f"  [SLIPPED] {label}")
            else:
                print(f"  [caught]  {label}")
    finally:
        # Restore by REGENERATING rather than by writing `original` back: if
        # this process was cut off earlier, `check_be_parity.py` regenerates
        # the file at step 1 anyway, so it is never skewed for long.
        regenerate()

    total = len(INJECTIONS) + len(TABLE_INJECTIONS)
    print()
    print("=" * 72)
    print(f"{total - len(slipped)}/{total} injected errors were caught")
    if slipped:
        print("SLIPPED — the checker does not compare these parts:")
        for x in slipped:
            print("  -", x)
        return 1
    print("The parity checker really does compare, number by number.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
